import { Directive, inject, InjectionToken, NgModule } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { LabelPassThrough } from 'primeng/types/label';
import { LabelStyle } from './style/labelstyle';

const LABEL_INSTANCE = new InjectionToken<Label>('LABEL_INSTANCE');

/**
 * Label directive is an extension to standard label element with theming.
 * @group Components
 */
@Directive({
    selector: 'label[pLabel]',
    standalone: true,
    host: {
        '[class]': "cx('root')"
    },
    providers: [LabelStyle, { provide: LABEL_INSTANCE, useExisting: Label }, { provide: PARENT_INSTANCE, useExisting: Label }],
    hostDirectives: [Bind]
})
export class Label extends BaseComponent<LabelPassThrough> {
    componentName = 'Label';

    _componentStyle = inject(LabelStyle);

    $pcLabel: Label | undefined = inject(LABEL_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}

@NgModule({
    imports: [Label],
    exports: [Label]
})
export class LabelModule {}
