import { Injectable } from '@angular/core';
import { style } from '@primeuix/styles/label';
import { BaseStyle } from 'primeng/base';

const classes = {
    root: 'p-label p-component'
};

@Injectable()
export class LabelStyle extends BaseStyle {
    name = 'label';

    style = style;

    classes = classes;
}

/**
 *
 * Label is used to create labels for form elements.
 *
 * [Live Demo](https://www.primeng.org/label/)
 *
 * @module labelstyle
 *
 */
export enum LabelClasses {
    /**
     * Class name of the root element
     */
    root = 'p-label'
}

export interface LabelStyle extends BaseStyle {}
